PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    MotorLatch : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT EStop, PT := T#0s);

IF SafetyTimer.Q THEN
    IF Start AND NOT Stop THEN
        MotorLatch := TRUE;
    ELSIF Stop THEN
        MotorLatch := FALSE;
    END_IF;
    Motor := MotorLatch;
ELSE
    Motor := FALSE;
END_IF;

END_PROGRAM

