PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    previousLevel : INT := 0;
    pumpTimer : TON;
END_VAR

pumpTimer(IN := TRUE, PT := T#2s);

IF Level >= 90 THEN
    ValveOut := TRUE;
    PumpIn := FALSE;
ELSIF Level <= 10 THEN
    ValveOut := FALSE;
    PumpIn := TRUE;
ELSE
    ValveOut := FALSE;
    IF NOT pumpTimer.Q AND Level > previousLevel THEN
        PumpIn := FALSE;
    ELSE
        PumpIn := TRUE;
    END_IF;
END_IF;

previousLevel := Level;
END_PROGRAM

