PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    HighLimit : INT := 90;
    LowLimit : INT := 10;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := PumpIn AND Level >= HighLimit, PT := T#1s);

IF SafetyTimer.Q THEN
    PumpIn := FALSE;
END_IF;

IF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := prev_PumpIn;
    ValveOut := prev_ValveOut;
END_IF;

prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;
END_PROGRAM

