PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    T1 : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
END_VAR

T1(IN := TRUE, PT := T#1s);

CASE State OF
    0: // Idle
        IF StartBatch AND NOT EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        IF Level >= LVL_HIGH OR EStop THEN
            State := 2;
        ELSE
            FillValve := TRUE;
        END_IF;

    2: // Heat
        IF Temp >= TEMP_SET OR EStop THEN
            State := 3;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;

    3: // React
        IF T1.Q OR EStop THEN
            State := 4;
        END_IF;

    4: // Drain
        IF Level <= LVL_LOW OR EStop THEN
            State := 0;
        ELSE
            DrainValve := TRUE;
        END_IF;
END_CASE;

FillValve := FALSE;
Heater := FALSE;
Agitator := FALSE;
DrainValve := FALSE;

IF NOT EStop OR Level < LIQ_MIN THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

