IF T_EStop.Q THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN THEN
    Heater := FALSE;
