END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    T1 : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
END_VAR

T1(IN := TRUE, PT := T#1s);

CASE State OF
    0: -- Idle
        IF StartBatch AND NOT EStop THEN
            State := 1;
        END_IF;

    1: -- Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH OR NOT StartBatch OR EStop THEN
            FillValve := FALSE;
            State := 2;
        END_IF;

    2: -- Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET OR EStop THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 3;
        END_IF;

    3: -- React
        Heater := TRUE;
        Agitator := TRUE;
        IF T1.Q OR EStop THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 4;
        END_IF;

    4: -- Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR EStop THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

-- Safety conditions
FillValve := NOT(EStop OR DrainValve);
Heater := NOT(EStop OR Level < LIQ_MIN);
Agitator := NOT(EStop OR Level < LIQ_MIN);
DrainValve := NOT(EStop OR FillValve);

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

FillTimer(IN := NOT EStop AND StartBatch AND Level >= LIQ_MIN, PT := T#1s);
DrainTimer(IN := NOT EStop AND State = 4 AND Level <= LVL_LOW, PT := T#1s);

CASE State OF
    0: // Idle
        IF NOT EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            FillValve := FALSE;
            State := 2;
        END_IF;

    2: // Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET OR NOT EStop THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 3;
        END_IF;

    3: // React
        Heater := TRUE;
        Agitator := TRUE;
        IF DrainTimer.Q THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        DrainValve := TRUE;
        IF NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

