END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
    FillTimer(IN := FALSE);
    HeatTimer(IN := FALSE);
END_IF;

CASE State OF
    0:
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            FillTimer(IN := TRUE, PT := T#0s);
        END_IF;
    1:
        IF FillTimer.Q OR Level >= LVL_HIGH THEN
            FillValve := FALSE;
            State := 2;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            HeatTimer(IN := TRUE, PT := T#0s);
        END_IF;
    2:
        IF HeatTimer.Q AND Temp >= TEMP_SET THEN
            State := 3;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            HeatTimer(IN := TRUE, PT := T#0s);
        END_IF;
    3:
        IF HeatTimer.T#0s >= PT_REACT THEN
            State := 4;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            HeatTimer(IN := TRUE, PT := T#0s);
        END_IF;
    4:
        IF DrainValve AND Level <= LVL_LOW THEN
            DrainValve := FALSE;
            State := 0;
            Heater := FALSE;
            Agitator := FALSE;
            FillValve := FALSE;
        END_IF;
END_CASE;

END_PROGRAM

