            FillValve := FALSE;
            State := 2;
        END_IF;

    2: -- Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: -- React
        Heater := TRUE;
        Agitator := TRUE;
        IF ReactTimer(IN := TRUE, PT := T#3s).Q THEN
            State := 4;
        END_IF;

    4: -- Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

