PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    ReactTimer : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
    FillTimer(IN := TRUE, PT := T#0s);
ELSIF State = 1 AND FillTimer.Q AND Level >= LVL_HIGH THEN
    State := 2;
    FillValve := FALSE;
ELSIF State = 2 AND Temp >= TEMP_SET THEN
    State := 3;
    ReactTimer(IN := TRUE, PT := T#0s);
ELSIF State = 3 AND ReactTimer.Q THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0;
ELSIF State = 1 OR State = 4 THEN
    IF Level < LIQ_MIN THEN
        State := 0;
    ELSE
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    END_IF;
ELSIF State = 2 THEN
    IF Level < LIQ_MIN OR Temp < TEMP_SET THEN
        State := 0;
    ELSE
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    END_IF;
ELSIF State = 3 THEN
    IF Level < LIQ_MIN OR Temp < TEMP_SET THEN
        State := 0;
    ELSE
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    END_IF;
END_IF;

END_PROGRAM

