PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

FillTimer(IN := NOT EStop AND (State = 1 OR (State = 0 AND StartCycle)), PT := T#5s);
DrainTimer(IN := NOT EStop AND State = 2, PT := T#5s);

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF NOT EStop AND StartCycle AND Level < 90 THEN
            State := 1;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF Level >= 90 OR EStop THEN
            State := 2;
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= 10 OR EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

